"""Curated GPS conflict / truck road traps; published rules are supported by the linked authority.
Coordinates and small SVG line segments are *approximate illustrative anchors*, never precise road geometry.
Author: Marc Lavoie | 2026-11-17.
"""
from pathlib import Path
import json
from pyproj import Transformer
root=Path(__file__).resolve().parents[1]
project=Transformer.from_crs('EPSG:4269','EPSG:5070',always_xy=True)
west,east,bottom,top=-2356114,2258201,272000,3172569
s=1050/(east-west)
def xy(lat,lon):
 a,b=project.transform(lon,lat)
 return [round(93+(a-west)*s,2),round(24+(top-b)*s,2)]
records=[]
def add(id,title,state,region,category,rule,limit,lat,lon,geometry,why,restriction,action,authority,url,classification='sourced',verification='2026-11-17'):
 # geometry is two ordered lat/lon anchor pairs; drawn as illustrative marker traces, NOT road lines.
 coords=[xy(*p) for p in geometry]
 x,y=xy(lat,lon)
 records.append(dict(id=id,title=title,state=state,region=region,category=category,rule=rule,limit=limit,lat=lat,lon=lon,x=x,y=y,trace=coords,
                     why=why,restriction=restriction,action=action,authority=authority,url=url,classification=classification,verifiedOn=verification,
                     mapAccuracy='Approximate regional marker and schematic connector; not surveyed road geometry.',sourceType='Official authority summary, not an active alert'))
NYC='https://www.nyc.gov/html/dot/html/motorist/parkway-restrictions.shtml'
NYFDR='https://www.nyc.gov/html/dot/html/pr2017/pr17-075.shtml'
CT='https://portal.ct.gov/dot/home/travel-gateway/roads-and-highways/parkway-restrictions'
MA='https://www.mass.gov/info-details/alert-for-fifa-tourists-and-travelers-on-dcr-river-road-height-restrictions'
CAL='https://dot.ca.gov/programs/traffic-operations/legal-truck-access/restrict-list'
