assert len(records)==30,len(records)
assert len({r['id'] for r in records})==len(records)
(root/'assets/data/road-traps.json').write_text(json.dumps(records,indent=2,ensure_ascii=False)+'\n')
(root/'assets/js/road-traps.js').write_text('/* ATLAS documented truck-route road trap library | Marc Lavoie | 2026-11-17 */\nwindow.ATLAS_ROAD_TRAPS='+json.dumps(records,separators=(',',':'),ensure_ascii=False)+';\n')
print('Generated',len(records),'road traps and',len({r['state'] for r in records}),'states')
